package com.example.paymentservice.dto.response;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.LocalDateTime;
public class InvoiceResponse { private Long invoiceId; private Long bookingId; private BigDecimal amount; private String status; private LocalDate issuedDate; private LocalDate dueDate; private LocalDateTime createdAt; private String createdBy; public Long getInvoiceId(){return invoiceId;} public void setInvoiceId(Long v){this.invoiceId=v;} public Long getBookingId(){return bookingId;} public void setBookingId(Long v){this.bookingId=v;} public BigDecimal getAmount(){return amount;} public void setAmount(BigDecimal v){this.amount=v;} public String getStatus(){return status;} public void setStatus(String v){this.status=v;} public LocalDate getIssuedDate(){return issuedDate;} public void setIssuedDate(LocalDate v){this.issuedDate=v;} public LocalDate getDueDate(){return dueDate;} public void setDueDate(LocalDate v){this.dueDate=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){this.createdAt=v;} public String getCreatedBy(){return createdBy;} public void setCreatedBy(String v){this.createdBy=v;} }